theory.code:
@ConditionalOnClass(X.class)        -> "Czy klasa X jest na classpath?"
@ConditionalOnMissingBean(Y.class)  -> "Czy uzytkownik JUZ zdefiniowal WLASNY bean typu Y?"
@ConditionalOnProperty(name="...")  -> "Czy ta wlasciwosc konfiguracyjna ma okreslona wartosc?"

@Bean
@ConditionalOnClass(ObjectMapper.class)
String jacksonStatusMessage() {
    return "Jackson jest dostepny na classpath";
}
// Zarejestruje sie TYLKO jesli com.fasterxml.jackson.databind.ObjectMapper istnieje na classpath

@Bean
@ConditionalOnMissingBean(MessageFormatter.class)
MessageFormatter defaultMessageFormatter() {
    return new DefaultMessageFormatter(); // domyslny wybor
}

// Jesli uzytkownik gdzie indziej zdefiniuje WLASNY bean MessageFormatter,
// powyzsza metoda @Bean NIE URUCHOMI SIE - auto-konfiguracja "wycofa sie" bez konfliktu

@ConditionalOnClass(X.class)          - bean powstaje TYLKO gdy klasa X jest na classpath
@ConditionalOnMissingClass("...")     - bean powstaje TYLKO gdy klasy NIE MA na classpath
@ConditionalOnBean(Y.class)           - bean powstaje TYLKO gdy bean typu Y JUZ istnieje
@ConditionalOnMissingBean(Y.class)    - bean powstaje TYLKO gdy bean typu Y jeszcze NIE istnieje
@ConditionalOnProperty(name="...", havingValue="...") - bean zalezny od wartosci wlasciwosci
@ConditionalOnWebApplication          - bean powstaje TYLKO w aplikacji webowej
@ConditionalOnExpression("...")       - bean zalezny od wyrazenia SpEL
